CREATE OR ALTER FUNCTION [utility].[GetObjectTypePath]
(
	@object varchar(20),
	@objectId int

)
RETURNS nvarchar(max)
AS
BEGIN
	declare @typeName nvarchar(max);

	select @typeName = TypeName from utility.objectdetail(@object,@objectId)

	if(@object = 'FusionAttribute')
	begin
		select @typeName = TX.[Path]
		from Asset A
		inner join AssetType T on T.ID = A.AssetTypeID and A.Object = 'FusionAttribute' and A.ObjectID = @objectId
		cross apply dbo.GetAssetTypeTextPathById(T.ID, '.') TX;		
	end

	return @typeName;
END
